  sleep() { this.awake = false; this.vx = this.vy = this.av = 0; this.sleepT = SLEEP_TIME; }
  speed() { return Math.hypot(this.vx, this.vy); }
  computeAABB() {
    const ac = Math.abs(this.c), as = Math.abs(this.s);
    const ex = ac * this.hw + as * this.hh + AABB_PAD;
    const ey = as * this.hw + ac * this.hh + AABB_PAD;
    this.minx = this.px - ex; this.maxx = this.px + ex;
    this.miny = this.py - ey; this.maxy = this.py + ey;
  }
}

/* --- box geometry tables: face normals & vertices in local space --------- */
const FN = [1, 0, 0, 1, -1, 0, 0, -1];      // outward normal of face i
const FV = [1, -1, 1, 1, -1, 1, -1, -1];    // vertex i (× hw, hh)

function worldVert(b, i, out) {
  const lx = FV[i * 2] * b.hw, ly = FV[i * 2 + 1] * b.hh;
  out.x = b.px + b.c * lx - b.s * ly;
  out.y = b.py + b.s * lx + b.c * ly;
}
function worldNorm(b, i, out) {
  const lx = FN[i * 2], ly = FN[i * 2 + 1];
  out.x = b.c * lx - b.s * ly;
  out.y = b.s * lx + b.c * ly;
}
function support(b, dx, dy, out) {
  const ldx = b.c * dx + b.s * dy;          // rotate direction into local space
  const ldy = -b.s * dx + b.c * dy;
  const lx = ldx >= 0 ? b.hw : -b.hw;
  const ly = ldy >= 0 ? b.hh : -b.hh;
  out.x = b.px + b.c * lx - b.s * ly;
  out.y = b.py + b.s * lx + b.c * ly;
}

/* --- narrowphase scratch (module-level to avoid per-call allocation) ----- */
const _n = { x: 0, y: 0 }, _p = { x: 0, y: 0 }, _v = { x: 0, y: 0 };
const _refN = { x: 0, y: 0 }, _tn = { x: 0, y: 0 };
const _ip0 = { x: 0, y: 0 }, _ip1 = { x: 0, y: 0 };
const _rv0 = { x: 0, y: 0 }, _rv1 = { x: 0, y: 0 };
const _mk = (n) => Array.from({ length: n }, () => ({ x: 0, y: 0, id: 0 }));
const _cIn = _mk(2), _cMid = _mk(2), _cOut = _mk(2);
const _sepRes = { s: 0, i: 0 };

/** Deepest penetration of B against every face of A. */
function maxSeparation(A, B) {
  let best = -1e30, bi = 0;
  for (let i = 0; i < 4; i++) {
    worldNorm(A, i, _n);
    support(B, -_n.x, -_n.y, _p);
    worldVert(A, i, _v);
    const s = _n.x * (_p.x - _v.x) + _n.y * (_p.y - _v.y);
    if (s > best) { best = s; bi = i; }
  }
  _sepRes.s = best; _sepRes.i = bi;
  return _sepRes;
}

/** Clip segment `inA` against half-plane (n·p - off <= 0). Returns count. */
function clipSegment(inA, outA, nx, ny, off) {
  let o = 0;
  const d0 = nx * inA[0].x + ny * inA[0].y - off;
  const d1 = nx * inA[1].x + ny * inA[1].y - off;
  if (d0 <= 0) { outA[o].x = inA[0].x; outA[o].y = inA[0].y; outA[o].id = inA[0].id; o++; }
  if (d1 <= 0) { outA[o].x = inA[1].x; outA[o].y = inA[1].y; outA[o].id = inA[1].id; o++; }
  if (d0 * d1 < 0 && o < 2) {
    const t = d0 / (d0 - d1);
    outA[o].x = inA[0].x + t * (inA[1].x - inA[0].x);
    outA[o].y = inA[0].y + t * (inA[1].y - inA[0].y);
    outA[o].id = d0 < 0 ? inA[1].id : inA[0].id;
    o++;
  }
  return o;
}

class ContactPoint {
  constructor() {
    this.x = 0; this.y = 0;            // world contact position
    this.lax = 0; this.lay = 0;        // anchor in A local space
    this.lbx = 0; this.lby = 0;        // anchor in B local space
    this.rax = 0; this.ray = 0;
    this.rbx = 0; this.rby = 0;
    this.sep = 0;                      // separation at manifold creation
    this.ni = 0; this.ti = 0;          // accumulated normal / tangent impulses
    this.nmass = 0; this.tmass = 0;
    this.vbias = 0;
    this.fid = -1;                     // feature id (warm-start matching)
  }
}

class Manifold {
  constructor(A, B) {
    this.A = A; this.B = B;
    this.nx = 0; this.ny = 0;          // normal points from A towards B
    this.count = 0;
    this.pts = [new ContactPoint(), new ContactPoint()];
    this.fric = 0; this.rest = 0;
    this.stamp = -1;
    this.totalImpulse = 0;
    // 2x2 block-solver terms (see solveVelocities)
    this.block = false;
    this.k11 = 0; this.k12 = 0; this.k22 = 0; this.invDet = 0;
  }
}

/**
 * Build the contact manifold for two boxes. Returns number of contact points.
 * Impulses of matching features are carried over from the previous frame.
 */
function collide(m) {
  const A = m.A, B = m.B;

  const sa = maxSeparation(A, B); const saS = sa.s, saI = sa.i;
  if (saS > SPEC_MARGIN) return (m.count = 0);
  const sb = maxSeparation(B, A); const sbS = sb.s, sbI = sb.i;
  if (sbS > SPEC_MARGIN) return (m.count = 0);

  let ref, inc, refI, flip;
  if (sbS > saS + 0.1 * SLOP) { ref = B; inc = A; refI = sbI; flip = true; }
  else                        { ref = A; inc = B; refI = saI; flip = false; }

  worldNorm(ref, refI, _refN);

  // incident face = the one most anti-parallel to the reference normal
  let minD = 1e30, incI = 0;
  for (let i = 0; i < 4; i++) {
    worldNorm(inc, i, _tn);
    const d = _tn.x * _refN.x + _tn.y * _refN.y;
    if (d < minD) { minD = d; incI = i; }
  }
  worldVert(inc, incI, _ip0);
  worldVert(inc, (incI + 1) & 3, _ip1);
  worldVert(ref, refI, _rv0);
  worldVert(ref, (refI + 1) & 3, _rv1);

  let tx = _rv1.x - _rv0.x, ty = _rv1.y - _rv0.y;
  const tl = Math.hypot(tx, ty);
  if (tl < 1e-9) return (m.count = 0);
  tx /= tl; ty /= tl;

  _cIn[0].x = _ip0.x; _cIn[0].y = _ip0.y; _cIn[0].id = incI;
  _cIn[1].x = _ip1.x; _cIn[1].y = _ip1.y; _cIn[1].id = (incI + 1) & 3;

  // clip against both side planes of the reference face
  if (clipSegment(_cIn, _cMid, -tx, -ty, -(tx * _rv0.x + ty * _rv0.y)) < 2) return (m.count = 0);
  if (clipSegment(_cMid, _cOut, tx, ty, tx * _rv1.x + ty * _rv1.y) < 2) return (m.count = 0);

  const nx = flip ? -_refN.x : _refN.x;
  const ny = flip ? -_refN.y : _refN.y;
  m.nx = nx; m.ny = ny;

  const old0 = m.pts[0], old1 = m.pts[1], oldCount = m.count;
  const oi0 = oldCount > 0 ? old0.fid : -1, oi1 = oldCount > 1 ? old1.fid : -1;
  const on0 = old0.ni, ot0 = old0.ti, on1 = old1.ni, ot1 = old1.ti;

  let n = 0;
  for (let k = 0; k < 2; k++) {
    const cp = _cOut[k];
    const sep = _refN.x * (cp.x - _rv0.x) + _refN.y * (cp.y - _rv0.y);
    if (sep > SPEC_MARGIN) continue;
    const p = m.pts[n];
    p.x = cp.x; p.y = cp.y; p.sep = sep;
    p.fid = (flip ? 1000 : 0) + refI * 100 + incI * 10 + cp.id;
    // warm start from the matching feature of the previous frame
    if (p.fid === oi0)      { p.ni = on0; p.ti = ot0; }
    else if (p.fid === oi1) { p.ni = on1; p.ti = ot1; }
    else                    { p.ni = 0;   p.ti = 0;   }
    n++;
  }
  m.count = n;
  return n;
}

/* --- spatial hash broadphase --------------------------------------------
   The depth layers all sit in the same plane, so a purely spatial hash would
   pile every layer into the same bucket and leave the layer filter to throw
   four fifths of the candidate pairs away *after* paying for them. Layer is
   part of the key instead. Bodies that collide with everything (layer -1 —
   the car) go into every layer's bucket, which costs a handful of inserts. */
class Grid {
  constructor(cell) {
    this.cell = cell; this.map = new Map(); this.layers = 1;
    this.pool = []; this.poolN = 0;      // recycled buckets, see clear()
  }
  key(gx, gy, layer) { return ((gx + 4096) * 8192 + (gy + 4096)) * 8 + layer; }
  /* Buckets are recycled rather than dropped. Rebuilding the hash from scratch
     each frame meant a fresh array per occupied cell, which at ~1900 bodies is
     half a megabyte per frame handed to the collector — and that comes back as
     a GC pause precisely when the crash is at its busiest and the frame budget
     is already tight. The pool holds at most one frame's worth of buckets. */
  clear() {
    for (const arr of this.map.values()) { arr.length = 0; this.pool[this.poolN++] = arr; }
    this.map.clear();
  }
  insert(b) {
    const c = this.cell;
    const x0 = Math.floor(b.minx / c), x1 = Math.floor(b.maxx / c);
    const y0 = Math.floor(b.miny / c), y1 = Math.floor(b.maxy / c);
    const lo = b.layer < 0 ? 0 : b.layer, hi = b.layer < 0 ? this.layers - 1 : b.layer;
    for (let gx = x0; gx <= x1; gx++) {
      for (let gy = y0; gy <= y1; gy++) {
        for (let L = lo; L <= hi; L++) {
          const k = this.key(gx, gy, L);
          let arr = this.map.get(k);
          if (arr === undefined) {
            arr = this.poolN > 0 ? this.pool[--this.poolN] : [];
            this.map.set(k, arr);
          }
          arr.push(b);
        }
      }
    }
  }
}

class World {
  constructor(gravity, cellSize) {
    this.bodies = [];
    this.statics = [];
    this.dynamics = [];
    this.gravity = gravity;
    this.manifolds = new Map();
    this.grid = new Grid(cellSize);
    this.stamp = 0;
    this.time = 0;
    this.impacts = [];            // {x,y,mag,nx,ny} — consumed by the FX layer
    this.frictionOverride = null; // (A,B) => number | null
    this.onManifold = null;       // (m) => void
  }
  add(b) {
    this.bodies.push(b);
    (b.isStatic ? this.statics : this.dynamics).push(b);
    return b;
  }
  key(a, b) { return a * 65536 + b; }

  /* ---- integrate external forces ---- */
  integrateVelocities(dt) {
    const g = this.gravity;
    const D = this.dynamics;
    for (let i = 0; i < D.length; i++) {
      const b = D[i];
      if (!b.awake) continue;
      b.vy += g * dt;
      b.vx *= 0.9995; b.vy *= 0.9995; b.av *= 0.998;   // faint air drag
      if (b.av > 42) b.av = 42; else if (b.av < -42) b.av = -42;
      const sp = b.vx * b.vx + b.vy * b.vy;
      if (sp > 40000) { const k = 200 / Math.sqrt(sp); b.vx *= k; b.vy *= k; }
    }
  }

  /* ---- broadphase + narrowphase ---- */
  updateContacts() {
    const stamp = ++this.stamp;
    const D = this.dynamics, S = this.statics, grid = this.grid;

    grid.clear();
    for (let i = 0; i < D.length; i++) { D[i].computeAABB(); grid.insert(D[i]); }
    for (let i = 0; i < S.length; i++) S[i].computeAABB();

    // dynamic <-> dynamic
    for (const cellBodies of grid.map.values()) {
      const L = cellBodies.length;
      if (L < 2) continue;
      for (let i = 0; i < L; i++) {
        const A = cellBodies[i];
        for (let j = i + 1; j < L; j++) {
          const B = cellBodies[j];
          if (!A.awake && !B.awake) continue;
          if (A.layer >= 0 && B.layer >= 0 && A.layer !== B.layer) continue;
          if (A.maxx < B.minx || B.maxx < A.minx || A.maxy < B.miny || B.maxy < A.miny) continue;
          const lo = A.id < B.id ? A : B, hi = A.id < B.id ? B : A;
          this.narrow(lo, hi, this.key(lo.id, hi.id), stamp);
        }
      }
    }
    // dynamic <-> static (few statics: direct test, no grid needed)
    for (let s = 0; s < S.length; s++) {
      const St = S[s];
      for (let i = 0; i < D.length; i++) {
        const B = D[i];
        if (!B.awake) continue;
        if (St.maxx < B.minx || B.maxx < St.minx || St.maxy < B.miny || B.maxy < St.miny) continue;
        const lo = St.id < B.id ? St : B, hi = St.id < B.id ? B : St;
        this.narrow(lo, hi, this.key(lo.id, hi.id), stamp);
      }
    }

    for (const [k, m] of this.manifolds) if (m.stamp !== stamp) this.manifolds.delete(k);
  }

  narrow(A, B, k, stamp) {
    let m = this.manifolds.get(k);
    if (m === undefined) { m = new Manifold(A, B); this.manifolds.set(k, m); }
    // A pair straddling a cell boundary is reached from every cell it shares,
    // and the stamp already records that this frame has dealt with it — so it
    // doubles as the duplicate filter, and the per-frame set of seen pairs it
    // replaces was itself thousands of insertions of pure overhead.
    else if (m.stamp === stamp) return;
    // Stamp on consideration, not on contact: a manifold that momentarily
    // reports zero points keeps its accumulated impulses for when the pair
    // touches again a frame later.
    m.stamp = stamp;
    if (collide(m) > 0) {
      // wake a sleeping neighbour that is being touched by something moving
      if (!A.isStatic && !B.isStatic) {
        if (A.awake && !B.awake) B.wake();
        else if (B.awake && !A.awake) A.wake();
      }
      if (this.onManifold) this.onManifold(m);
    }
  }

  /* ---- prepare constraints ----
     Every restitution decision is made from the velocities as they stand at
     the top of the step. Warm starting happens afterwards, in its own pass
     (warmStart), because a warm-start impulse applied at one contact point
     spins the body before the next point has been measured — and a box that
     appears to be closing at 1 m/s when it is actually at rest gets handed a
     bounce it never earned. That is free energy, and a tall stack collects
     enough of it to walk itself over. */
  prestep(invDt) {
    for (const m of this.manifolds.values()) {
      const A = m.A, B = m.B, nx = m.nx, ny = m.ny;
      const ov = this.frictionOverride && this.frictionOverride(A, B);
      m.fric = ov === null || ov === undefined ? Math.sqrt(A.fric * B.fric) : ov;
      m.rest = Math.min(A.rest, B.rest);
      m.totalImpulse = 0;
      const tx = -ny, ty = nx;

      for (let i = 0; i < m.count; i++) {
        const p = m.pts[i];
        p.rax = p.x - A.px; p.ray = p.y - A.py;
        p.rbx = p.x - B.px; p.rby = p.y - B.py;
        // cache anchors in local space for the position pass
        p.lax =  p.rax * A.c + p.ray * A.s;
        p.lay = -p.rax * A.s + p.ray * A.c;
        p.lbx =  p.rbx * B.c + p.rby * B.s;
        p.lby = -p.rbx * B.s + p.rby * B.c;

        const rnA = p.rax * ny - p.ray * nx;
        const rnB = p.rbx * ny - p.rby * nx;
        const kn = A.invMass + B.invMass + A.invI * rnA * rnA + B.invI * rnB * rnB;
        p.nmass = kn > 0 ? 1 / kn : 0;

        const rtA = p.rax * ty - p.ray * tx;
        const rtB = p.rbx * ty - p.rby * tx;
        const kt = A.invMass + B.invMass + A.invI * rtA * rtA + B.invI * rtB * rtB;
        p.tmass = kt > 0 ? 1 / kt : 0;

        const dvx = (B.vx - B.av * p.rby) - (A.vx - A.av * p.ray);
        const dvy = (B.vy + B.av * p.rbx) - (A.vy + A.av * p.rax);
        const vn = dvx * nx + dvy * ny;

        if (p.sep > 0) p.vbias = -p.sep * invDt;              // speculative limit
        else if (vn < -REST_THRESH) p.vbias = -m.rest * vn;   // bounce
        else p.vbias = 0;
      }

      /* Two-point manifolds get a simultaneous 2x2 solve. Resolving the two
         points one after the other (pure Gauss-Seidel) always lands the first
         impulse before the second, which leaves a residual torque on every
         box — a stack of them slowly rocks itself apart. Precompute the
         coupled mass matrix here; ill-conditioned pairs fall back to the
         sequential path. */
      if (m.count === 2) {
        const p1 = m.pts[0], p2 = m.pts[1];
        const rn1A = p1.rax * ny - p1.ray * nx, rn1B = p1.rbx * ny - p1.rby * nx;
        const rn2A = p2.rax * ny - p2.ray * nx, rn2B = p2.rbx * ny - p2.rby * nx;
        const im = A.invMass + B.invMass;
        const k11 = im + A.invI * rn1A * rn1A + B.invI * rn1B * rn1B;
        const k22 = im + A.invI * rn2A * rn2A + B.invI * rn2B * rn2B;
        const k12 = im + A.invI * rn1A * rn2A + B.invI * rn1B * rn2B;
        const det = k11 * k22 - k12 * k12;
        if (det > 0 && k11 * k11 < 1000 * det) {
          m.block = true; m.k11 = k11; m.k12 = k12; m.k22 = k22; m.invDet = 1 / det;
        } else m.block = false;
      } else m.block = false;
    }
  }

  /* ---- replay last step's impulses (see prestep) ---- */
  warmStart() {
    for (const m of this.manifolds.values()) {
      const A = m.A, B = m.B, nx = m.nx, ny = m.ny, tx = -ny, ty = nx;
      for (let i = 0; i < m.count; i++) {
        const p = m.pts[i];
        const px = p.ni * nx + p.ti * tx;
        const py = p.ni * ny + p.ti * ty;
        A.vx -= px * A.invMass; A.vy -= py * A.invMass;
        A.av -= A.invI * (p.rax * py - p.ray * px);
        B.vx += px * B.invMass; B.vy += py * B.invMass;
        B.av += B.invI * (p.rbx * py - p.rby * px);
      }
    }
  }

  /* ---- velocity constraints (friction first, then normal) ---- */
  solveVelocities(iters) {
    for (let it = 0; it < iters; it++) {
      const last = it === iters - 1;
      for (const m of this.manifolds.values()) {
        const A = m.A, B = m.B, nx = m.nx, ny = m.ny, tx = -ny, ty = nx;

        // ---- friction (always sequential; bound by the current normal load)
        for (let i = 0; i < m.count; i++) {
          const p = m.pts[i];
          const dvx = (B.vx - B.av * p.rby) - (A.vx - A.av * p.ray);
          const dvy = (B.vy + B.av * p.rbx) - (A.vy + A.av * p.rax);
          const vt = dvx * tx + dvy * ty;
          let dl = -p.tmass * vt;
          const maxF = m.fric * p.ni;
          const oldT = p.ti;
          p.ti = clamp(oldT + dl, -maxF, maxF);
          dl = p.ti - oldT;
          const ix = dl * tx, iy = dl * ty;
          A.vx -= ix * A.invMass; A.vy -= iy * A.invMass;
          A.av -= A.invI * (p.rax * iy - p.ray * ix);
          B.vx += ix * B.invMass; B.vy += iy * B.invMass;
          B.av += B.invI * (p.rbx * iy - p.rby * ix);
        }

        // ---- normal
        if (m.block) {
          // Simultaneous 2-point solve: find x >= 0 with A*x + b = 0, trying
          // each active set in turn (both points, either one, neither).
          const p1 = m.pts[0], p2 = m.pts[1];
          const a1 = p1.ni, a2 = p2.ni;
          let dvx = (B.vx - B.av * p1.rby) - (A.vx - A.av * p1.ray);
          let dvy = (B.vy + B.av * p1.rbx) - (A.vy + A.av * p1.rax);
          const vn1 = dvx * nx + dvy * ny;
          dvx = (B.vx - B.av * p2.rby) - (A.vx - A.av * p2.ray);
          dvy = (B.vy + B.av * p2.rbx) - (A.vy + A.av * p2.rax);
          const vn2 = dvx * nx + dvy * ny;

          const b1 = vn1 - p1.vbias - (m.k11 * a1 + m.k12 * a2);
          const b2 = vn2 - p2.vbias - (m.k12 * a1 + m.k22 * a2);

          let x1 = -(m.k22 * b1 - m.k12 * b2) * m.invDet;
          let x2 = -(m.k11 * b2 - m.k12 * b1) * m.invDet;
          let ok = x1 >= 0 && x2 >= 0;
          if (!ok) { x1 = -b1 / m.k11; x2 = 0; ok = x1 >= 0 && m.k12 * x1 + b2 >= 0; }
          if (!ok) { x1 = 0; x2 = -b2 / m.k22; ok = x2 >= 0 && m.k12 * x2 + b1 >= 0; }
          if (!ok) { x1 = 0; x2 = 0; ok = b1 >= 0 && b2 >= 0; }

          if (ok) {
            const d1 = x1 - a1, d2 = x2 - a2;
            const ix = (d1 + d2) * nx, iy = (d1 + d2) * ny;
            A.vx -= ix * A.invMass; A.vy -= iy * A.invMass;
            A.av -= A.invI * (p1.rax * (d1 * ny) - p1.ray * (d1 * nx)
                            + p2.rax * (d2 * ny) - p2.ray * (d2 * nx));
            B.vx += ix * B.invMass; B.vy += iy * B.invMass;
            B.av += B.invI * (p1.rbx * (d1 * ny) - p1.rby * (d1 * nx)
                            + p2.rbx * (d2 * ny) - p2.rby * (d2 * nx));
            p1.ni = x1; p2.ni = x2;
          }
        } else {
          for (let i = 0; i < m.count; i++) {
            const p = m.pts[i];
            const dvx = (B.vx - B.av * p.rby) - (A.vx - A.av * p.ray);
            const dvy = (B.vy + B.av * p.rbx) - (A.vy + A.av * p.rax);
            const vn = dvx * nx + dvy * ny;
            let dl = -p.nmass * (vn - p.vbias);
            const oldN = p.ni;
            p.ni = oldN + dl > 0 ? oldN + dl : 0;
            dl = p.ni - oldN;
            const ix = dl * nx, iy = dl * ny;
            A.vx -= ix * A.invMass; A.vy -= iy * A.invMass;
            A.av -= A.invI * (p.rax * iy - p.ray * ix);
            B.vx += ix * B.invMass; B.vy += iy * B.invMass;
