      if (m.count === 0) continue;
      const A = m.A, B = m.B, nx = m.nx, ny = m.ny;
      const corr = [0, 0], rxA = [0, 0], ryA = [0, 0], rxB = [0, 0], ryB = [0, 0];
      for (let i = 0; i < m.count; i++) {
        const p = m.pts[i];
        const rax = A.c * p.lax - A.s * p.lay;
        const ray = A.s * p.lax + A.c * p.lay;
        const rbx = B.c * p.lbx - B.s * p.lby;
        const rby = B.s * p.lbx + B.c * p.lby;
        rxA[i] = rax; ryA[i] = ray; rxB[i] = rbx; ryB[i] = rby;
        const ax = A.px + rax, ay = A.py + ray;
        const bx = B.px + rbx, by = B.py + rby;
        const sep = (bx - ax) * nx + (by - ay) * ny;
        corr[i] = clamp(BAUMGARTE * (sep + SLOP), -0.12, 0);
      }
      for (let i = 0; i < m.count; i++) {
        const rnA = rxA[i] * ny - ryA[i] * nx;
        const rnB = rxB[i] * ny - ryB[i] * nx;
        const kn = A.invM + B.invM + A.invI * rnA * rnA + B.invI * rnB * rnB;
        const d = kn > 0 ? -corr[i] / kn : 0;
        const ix = d * nx, iy = d * ny;
        if (!A.static && A.awake) {
          A.px -= ix * A.invM; A.py -= iy * A.invM;
          A.ang -= A.invI * (rxA[i] * iy - ryA[i] * ix);
        }
        if (!B.static && B.awake) {
          B.px += ix * B.invM; B.py += iy * B.invM;
          B.ang += B.invI * (rxB[i] * iy - ryB[i] * ix);
        }
      }
      if (!A.static && A.awake) A.updateRot();
      if (!B.static && B.awake) B.updateRot();
    }
  }
}

