const fs = require("fs");
const values = { sSpeed: "22", sCols: "12", sRows: "8", sLayers: "2", sMass: "2.5" };
const els = {};
function makeEl(id) {
  return {
    id, value: values[id] || "", innerHTML: "", textContent: "",
    dataset: {}, style: { width: "", height: "" }, width: 1440, height: 900,
    classList: { toggle(){ return false; }, remove(){}, add(){}, contains(){ return false; } },
    setAttribute(){}, addEventListener(){},
    getContext() {
      const grad = { addColorStop(){} };
      return new Proxy({ createLinearGradient: () => grad, createRadialGradient: () => grad, measureText: () => ({ width: 10 }) }, { get(t, p) { return t[p] || (() => grad); } });
    }
  };
}
global.window = global;
global.innerWidth = 1440; global.innerHeight = 900; global.devicePixelRatio = 1;
global.matchMedia = () => ({ matches: false, addEventListener(){} });
let raf = null, clock = 1000;
global.requestAnimationFrame = (cb) => { raf = cb; return 1; };
global.addEventListener = () => {};
global.document = { getElementById: (id) => els[id] || (els[id] = makeEl(id)), addEventListener(){} };
eval(fs.readFileSync("/tmp/car-crash-sim.js", "utf8"));

function stepMs(ms) {
  const n = Math.ceil(ms / 16.67);
  for (let i = 0; i < n; i++) {
    clock += 16.67;
    if (raf) raf(clock);
  }
}

function run(label, set) {
  Object.assign(values, set);
  for (const [k,v] of Object.entries(set)) if (els[k]) els[k].value = v;
  global.__crash.test();
  stepMs(1800);
  const s = global.__crash.snap();
  console.log(label, JSON.stringify({
    elapsed: +s.elapsed.toFixed(3), vx: +s.vx.toFixed(3), px: +s.px.toFixed(3), py: +s.py.toFixed(3),
